--- a/src/internal.c
+++ b/src/internal.c
@@ -10003,6 +10003,18 @@
 #endif

     while (ssl->buffers.outputBuffer.length > 0) {
+        if (ssl->buffers.outputBuffer.idx > ssl->buffers.outputBuffer.bufferSize ||
+                ssl->buffers.outputBuffer.length >
+                    ssl->buffers.outputBuffer.bufferSize -
+                    ssl->buffers.outputBuffer.idx) {
+            WOLFSSL_MSG("SendBuffered() output buffer state invalid");
+            ssl->buffers.outputBuffer.length = 0;
+            ssl->buffers.outputBuffer.idx = 0;
+            if (ssl->buffers.outputBuffer.dynamicFlag)
+                ShrinkOutputBuffer(ssl);
+            return SEND_OOB_READ_E;
+        }
+
         int sent = ssl->CBIOSend(ssl,
                                       (char*)ssl->buffers.outputBuffer.buffer +
                                       ssl->buffers.outputBuffer.idx,

